import sys
input = sys.stdin.read

def solve(n, k):
    if k > n * n:
        return -1

    # Initialize an n x n matrix of zeroes
    matrix = [[0] * n for _ in range(n)]

    # Fill the matrix with ones symmetrically
    for i in range(n):
        if k <= 0:
            break
        # Try to place a '1' on the diagonal
        if k > 0:
            matrix[i][i] = 1
            k -= 1

        # Try to place pairs of '1's symmetrically
        for j in range(i + 1, n):
            if k >= 2:
                matrix[i][j] = matrix[j][i] = 1
                k -= 2
            else:
                break

    if k > 0:
        return -1
    else:
        return matrix

def main():
    data = input().strip()
    n, k = map(int, data.split())
    result = solve(n, k)

    if result == -1:
        print(-1)
    else:
        for row in result:
            print(" ".join(map(str, row)))

if __name__ == "__main__":
    main()

